def sortVowels(s):
    vowels = "aeiou"
    count = {}
    first = {}

    # Count each vowel and remember where it first appears
    for i, ch in enumerate(s):
        if ch in vowels:
            if ch not in count:
                count[ch] = 0
                first[ch] = i
            count[ch] += 1

    # Order the vowels present: higher count first, earlier first occurrence breaks ties
    present = list(count.keys())
    present.sort(key=lambda v: (-count[v], first[v]))

    # The vowels, in the order they must be written back
    sequence = []
    for v in present:
        sequence.extend(v * count[v])

    # Rebuild the string: consonants stay, vowel slots take the next vowel in order
    result = []
    pos = 0
    for ch in s:
        if ch in vowels:
            result.append(sequence[pos])
            pos += 1
        else:
            result.append(ch)

    return "".join(result)
